}

.item-icon-durability-fill {
  display: block;
  height: 2px;
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 18px;
  height: 18px;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.crosshair {
  mix-blend-mode: difference;
