toolUseResult.originalFile:
/* Full-screen overlays: pause menu, F3 debug readout, click-to-play hint. */

/* Shared dimmer behind any open menu (inventory or pause). Sits above the
   canvas/hotbar (z 4) and below the inventory (z 6) and pause menu (z 9), so a
   single element darkens the frozen world without double-dimming. */
.menu-backdrop {
  position: absolute;
  inset: 0;
  z-index: 5;
  background: rgba(0, 0, 0, 0.55);
  animation: mc-fade-in 140ms ease-out;
}

.pause-overlay {
  position: absolute;
  inset: 0;
  z-index: 9;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: mc-fade-in 140ms ease-out;
}

.pause-menu {
  display: grid;
  gap: 8px;
  width: min(92vw, 320px);
  justify-items: stretch;
}

.pause-title {
  text-align: center;
  color: var(--mc-text-light);
  font-size: 22px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
  margin-bottom: 10px;
}

.mc-button {
  padding: 9px 16px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: var(--mc-text-shadow);
  background: var(--mc-tile-button), var(--mc-button);
  border-style: solid;
  border-width: 2px;
  border-color: #a8a8a8 #2c2c2c #2c2c2c #a8a8a8;
  outline: 2px solid rgba(0, 0, 0, 0.85);
  cursor: pointer;
  user-select: none;
  transition: background-color 80ms ease;
}

.mc-button:hover,
.mc-button:focus-visible {
  background: var(--mc-button-hover);
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.mc-button:active {
  border-color: #2c2c2c #a8a8a8 #a8a8a8 #2c2c2c;
}

.mc-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.mc-button.danger {
  background: #8c3a34;
  border-color: #c98179 #4a1713 #4a1713 #c98179;
}

.pause-reset-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.pause-sound {
  display: grid;
  gap: 8px;
  margin-top: 4px;
}

.pause-sound-row {
  display: grid;
  grid-template-columns: 64px 1fr;
  align-items: center;
  gap: 10px;
  color: var(--mc-text-light);
  font-size: 13px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
}

.pause-skins {
  display: grid;
  gap: 6px;
  margin-top: 4px;
}

.pause-skins-title {
  color: var(--mc-text-light);
  font-size: 13px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
}

.pause-skins-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.skin-swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 6px 4px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: var(--mc-text-shadow);
  background: var(--mc-tile-button), var(--mc-button);
  border-style: solid;
  border-width: 2px;
  border-color: #a8a8a8 #2c2c2c #2c2c2c #a8a8a8;
  cursor: pointer;
  user-select: none;
}

.skin-swatch:hover,
.skin-swatch:focus-visible {
  background: var(--mc-button-hover);
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.skin-swatch[aria-pressed="true"] {
  background: var(--mc-button-hover);
  border-color: #f0be3c;
  outline: 1px solid rgba(240, 190, 60, 0.6);
}

.mc-slider {
  appearance: none;
  width: 100%;
  height: 18px;
  margin: 0;
  background: var(--mc-tile-button), var(--mc-button);
  border-style: solid;
  border-width: 2px;
  border-color: #2c2c2c #a8a8a8 #a8a8a8 #2c2c2c;
  outline: 2px solid rgba(0, 0, 0, 0.85);
  cursor: pointer;
}

.mc-slider:focus-visible {
  background: var(--mc-button-hover);
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.mc-slider::-webkit-slider-thumb {
  appearance: none;
  width: 12px;
  height: 18px;
  background: var(--mc-button-hover);
  border-style: solid;
  border-width: 2px;
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.mc-slider::-moz-range-thumb {
  width: 12px;
  height: 18px;
  border-radius: 0;
  background: var(--mc-button-hover);
  border-style: solid;
  border-width: 2px;
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.pause-save-message {
  text-align: center;
  color: #aef79f;
  font-size: 13px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
}

.pause-controls {
  margin-top: 12px;
  padding: 10px 12px;
  background: var(--mc-tile-dirt), rgba(20, 14, 8, 0.9);
  outline: 2px solid rgba(0, 0, 0, 0.85);
  display: grid;
  gap: 3px;
}

.pause-controls-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: #d4d4d4;
  font-size: 11px;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.7);
}

.pause-controls-row span:last-child {
  color: #f4f4f4;
  font-weight: 700;
}

.debug-overlay {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 5;
  display: grid;
  gap: 2px;
  justify-items: start;
  pointer-events: none;
  user-select: none;
}

.debug-line {
  background: rgba(16, 16, 16, 0.45);
  color: #e8e8e8;
  font-family: var(--mc-font-mono);
  font-size: 12px;
  line-height: 1.35;
  padding: 1px 5px;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.7);
  white-space: pre;
}

.click-hint {
  position: absolute;
  left: 50%;
  top: 38%;
  transform: translateX(-50%);
  z-index: 3;
  color: var(--mc-text-light);
  font-size: 15px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
  background: rgba(16, 16, 16, 0.45);
  padding: 6px 14px;
  outline: 2px solid rgba(0, 0, 0, 0.6);
  pointer-events: none;
  user-select: none;
  animation: click-hint-pulse 2.4s ease-in-out infinite;
}

@keyframes click-hint-pulse {
  0%,
  100% {
    opacity: 0.95;
  }
  50% {
    opacity: 0.55;
  }
}

